<section data-page-title="My Profile" data-page-script="profile.js"><div class="page-intro"><span class="eyebrow">Account</span><h2>Manage profile</h2><p>Update personal information and password.</p></div><div id="alertBox" class="alert"></div><div class="grid grid-2"><div class="card"><h3>Profile Information</h3><form id="profileForm" class="form-grid one"><div class="form-group"><label>Name</label><input class="input" name="name" required></div><div class="form-group"><label>Email</label><input class="input" name="email" type="email" required></div><div class="form-group"><label>Phone</label><input class="input" name="phone" required></div><div class="form-group"><label>Nationality</label><input class="input" name="nationality"></div><div class="form-group"><label>ID Number</label><input class="input" name="national_id"></div><button class="btn btn-gradient" type="submit">Update Profile</button></form></div><div class="card"><h3>Change Password</h3><form id="passwordForm" class="form-grid one"><div class="form-group"><label>Current Password</label><input class="input" type="password" name="current_password" required></div><div class="form-group"><label>New Password</label><input class="input" type="password" name="new_password" required></div><div class="form-group"><label>Confirm New Password</label><input class="input" type="password" name="confirm_password" required></div><button class="btn btn-primary" type="submit">Change Password</button></form></div></div></section>